CREATE TABLE `students` (`id` VARCHAR(191) NOT NULL, `student_number` VARCHAR(100) NOT NULL, `first_name` VARCHAR(191) NOT NULL, `last_name` VARCHAR(191) NOT NULL, `email` VARCHAR(191) NOT NULL, `metadata_json` JSON NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `students_student_number_key`(`student_number`), INDEX `students_last_name_first_name_idx`(`last_name`,`first_name`), INDEX `students_email_idx`(`email`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `class_students` (`class_id` VARCHAR(191) NOT NULL, `student_id` VARCHAR(191) NOT NULL, `enrollment_status` ENUM('ACTIVE','REMOVED') NOT NULL DEFAULT 'ACTIVE', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `class_students_class_id_enrollment_status_idx`(`class_id`,`enrollment_status`), PRIMARY KEY (`class_id`,`student_id`), CONSTRAINT `class_students_class_id_fkey` FOREIGN KEY (`class_id`) REFERENCES `classes`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `class_students_student_id_fkey` FOREIGN KEY (`student_id`) REFERENCES `students`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `roster_import_previews` (`id` VARCHAR(191) NOT NULL, `class_id` VARCHAR(191) NOT NULL, `actor_user_id` VARCHAR(191) NOT NULL, `source_filename` VARCHAR(255) NOT NULL, `rows_json` JSON NOT NULL, `valid_count` INTEGER NOT NULL, `error_count` INTEGER NOT NULL, `status` ENUM('READY','COMMITTED','EXPIRED') NOT NULL DEFAULT 'READY', `expires_at` DATETIME(3) NOT NULL, `committed_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `roster_import_previews_class_id_status_idx`(`class_id`,`status`), INDEX `roster_import_previews_expires_at_idx`(`expires_at`), PRIMARY KEY (`id`), CONSTRAINT `roster_import_previews_class_id_fkey` FOREIGN KEY (`class_id`) REFERENCES `classes`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `roster_import_previews_actor_user_id_fkey` FOREIGN KEY (`actor_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `badge_templates` (`id` VARCHAR(191) NOT NULL, `class_id` VARCHAR(191) NOT NULL, `owner_user_id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `criteria` TEXT NOT NULL, `image_path` VARCHAR(500) NOT NULL, `status` ENUM('ACTIVE','ARCHIVED') NOT NULL DEFAULT 'ACTIVE', `expires_after_days` INTEGER NULL, `metadata_json` JSON NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `badge_templates_class_id_status_idx`(`class_id`,`status`), INDEX `badge_templates_owner_user_id_idx`(`owner_user_id`), INDEX `badge_templates_name_idx`(`name`), PRIMARY KEY (`id`), CONSTRAINT `badge_templates_class_id_fkey` FOREIGN KEY (`class_id`) REFERENCES `classes`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `badge_templates_owner_user_id_fkey` FOREIGN KEY (`owner_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
